THEME = ("T09", "Mise en œuvre technique (annuaires, systèmes, réseaux, cloud)")
SOURCE = "Microsoft Learn, documentation Active Directory et NTFS ; RFC 4120 (Kerberos V5) ; RFC 4511 (LDAP) ; IEEE 802.1X-2020 ; man sudoers(5) ⚠ à vérifier"
Q = [
(1,"Que contient un annuaire comme Active Directory ?","Les identités, groupes et ressources d'une organisation","Les sauvegardes des serveurs","Les images des postes","Les mots de passe en clair",
 "Un annuaire centralise les objets sur lesquels s'appuie le contrôle d'accès."),
(1,"Que signifie LDAP ?","Lightweight Directory Access Protocol","Large Data Access Program","Local Domain Authentication Protocol","Linked Database Access Process",
 "LDAP est le protocole standard d'interrogation d'annuaires (RFC 4511)."),
(2,"Que désigne le DN dans un annuaire LDAP ?","Le nom distinctif qui identifie un objet de façon unique","Le nom du domaine seulement","Le numéro de disque","Le niveau de sécurité",
 "Par exemple CN=Marc Durand,OU=Exploitation,DC=translor,DC=local."),
(2,"Que désigne une OU dans Active Directory ?","Une unité d'organisation qui regroupe des objets et permet de déléguer l'administration","Une unité de stockage","Une option d'utilisateur","Un onglet d'ouverture",
 "Les OU structurent l'annuaire et servent de cible aux stratégies de groupe."),
(2,"Que désigne un SID sous Windows ?","L'identifiant de sécurité unique d'un compte ou d'un groupe","Un identifiant de session internet","Un système d'information distribué","Un statut d'installation",
 "Les droits NTFS référencent des SID, pas des noms."),
(2,"Pourquoi un compte supprimé puis recréé avec le même nom perd-il ses droits ?","Il reçoit un nouveau SID","Son mot de passe a changé","Son nom est trop court","Le groupe est vide",
 "Les ACL pointent vers l'ancien SID, qui n'existe plus."),
(2,"Que désigne une GPO ?","Une stratégie de groupe qui applique des paramètres à des utilisateurs ou ordinateurs","Un protocole de gestion de pare-feu","Un général de la protection des objets","Un groupe de postes obsolètes",
 "Les GPO déploient des paramètres de sécurité, par exemple la politique de mot de passe."),
(2,"Sur quoi une GPO est-elle liée pour s'appliquer ?","Un site, un domaine ou une OU","Un fichier texte","Une imprimante","Un câble",
 "L'application suit la hiérarchie de l'annuaire."),
(2,"Que signifie AGDLP ?","Comptes, groupes globaux, groupes de domaine local, permissions","Accès global des droits locaux et privés","Administration générale des listes de permissions","Annuaire, groupes, domaines, licences, politiques",
 "Account, Global group, Domain Local group, Permission : les utilisateurs entrent dans un groupe global de rôle, lequel entre dans un groupe local porteur des droits."),
(2,"Dans AGDLP, où place-t-on la permission sur la ressource ?","Sur le groupe de domaine local","Sur chaque compte","Sur le groupe global uniquement","Sur l'ordinateur de l'administrateur",
 "Les ressources sont protégées par des groupes locaux qui contiennent des groupes globaux de rôles."),
(2,"Quel est l'intérêt de la méthode AGDLP ?","Séparer le rôle métier de la ressource et simplifier les changements","Supprimer les groupes","Chiffrer les ressources","Éviter l'annuaire",
 "Un nouveau magasinier rejoint un groupe global ; ses droits suivent sans toucher aux ressources."),
(2,"Un nouveau magasinier arrive. Que fait-on dans AGDLP ?","On l'ajoute au groupe global « Magasiniers »","On lui donne des droits sur chaque dossier","On lui donne le mot de passe du responsable","On crée un nouveau domaine",
 "Les droits sont déjà associés au groupe local de chaque ressource."),
(2,"Quel protocole d'authentification sous Windows repose sur des tickets ?","Kerberos","Telnet","FTP","SNMP v1",
 "Kerberos V5 (RFC 4120) délivre un TGT puis des tickets de service."),
(2,"Que contient un TGT Kerberos ?","La preuve que le client s'est authentifié auprès du centre de distribution de clés","Le mot de passe du client","Le contenu d'un fichier","Un certificat de serveur web",
 "Le TGT permet de demander des tickets de service sans ressaisir le mot de passe."),
(2,"Que fait le KDC dans Kerberos ?","Délivre des tickets après authentification","Chiffre les fichiers","Fait la sauvegarde","Gère l'imprimante",
 "Key Distribution Center : composé de l'AS et du TGS."),
(3,"Quel type d'attaque exploite le vol d'un ticket Kerberos de service pour se faire passer pour un utilisateur ?","Pass-the-ticket","Déni de service","Hameçonnage d'usurpation de domaine","Injection SQL",
 "Le ticket volé permet d'accéder au service tant qu'il est valide."),
(3,"Quel type d'attaque exploite un hash de mot de passe NTLM sans le casser ?","Pass-the-hash","Pass-the-ticket","Attaque par dictionnaire hors ligne","Attaque par force brute en ligne",
 "Le hash lui-même sert d'authentifiant dans le protocole NTLM."),
(2,"Quelle bonne pratique réduit l'impact d'un vol d'identifiants administrateur ?","Des comptes d'administration distincts des comptes quotidiens et un modèle d'administration en niveaux","Un mot de passe identique partout","Aucun journal","Le partage du compte",
 "On évite qu'un identifiant privilégié soit exposé sur des postes à risque."),
(2,"Que signifie « 802.1X » ?","Un contrôle d'accès au réseau par authentification de port","Un protocole de messagerie","Un format d'image","Un chiffrement de disque",
 "Il authentifie un poste avant de lui accorder l'accès au réseau filaire ou Wi-Fi."),
(2,"Quel protocole transporte généralement les authentifications 802.1X vers un serveur central ?","RADIUS","SMTP","FTP","NTP",
 "Le serveur RADIUS décide d'accepter ou de refuser l'accès réseau."),
(2,"Quelle différence essentielle entre RADIUS et TACACS+ ?","TACACS+ sépare authentification, autorisation et comptabilité et chiffre tout le corps","RADIUS chiffre tout","TACACS+ est réservé aux imprimantes","Il n'y a aucune différence",
 "TACACS+ est souvent préféré pour l'administration d'équipements réseau."),
(2,"Comment une liste de contrôle d'accès de routeur évalue-t-elle les règles ?","De haut en bas, la première correspondance s'applique","Du bas en haut","Au hasard","Toutes en même temps",
 "L'ordre des règles est donc essentiel."),
(2,"Que se passe-t-il à la fin d'une ACL de routeur classique ?","Un refus implicite s'applique au trafic non prévu","Un permis implicite s'applique","Le routeur s'arrête","Le trafic est chiffré",
 "Sans règle correspondante, le paquet est rejeté : deny any implicite."),
(3,"Une ACL contient en ligne 1 « permit ip any any » puis en ligne 2 « deny tcp any any eq 23 ». Que se passe-t-il pour Telnet ?","Il est permis, car la ligne 1 correspond en premier","Il est refusé","Il est chiffré","Il est redirigé",
 "La règle générale placée trop haut masque les règles plus précises."),
(2,"Qu'est-ce qu'un VLAN ?","Un réseau local virtuel qui segmente la couche 2","Un type de câble","Un protocole de messagerie","Un chiffrement",
 "Les VLAN séparent des groupes de machines, mais le routage entre eux se contrôle par ACL ou pare-feu."),
(2,"Pourquoi un VLAN seul ne suffit-il pas comme contrôle d'accès ?","Rien n'empêche le routage entre VLAN sans règles de filtrage","Il est trop lent","Il est chiffré","Il supprime les ports",
 "Il faut y associer des règles de filtrage entre zones."),
(2,"Que fait un pare-feu à états ?","Suit les connexions et n'accepte que le trafic de retour légitime","Chiffre les paquets","Supprime les journaux","Compresse les paquets",
 "Il décide selon l'état de la session, pas seulement paquet par paquet."),
(2,"Quel principe applique-t-on aux règles de pare-feu ?","Refuser par défaut puis ouvrir uniquement le nécessaire","Autoriser par défaut","Ouvrir tous les ports","Supprimer les règles",
 "C'est l'application du moindre privilège au réseau."),
(2,"Quelle commande permet à un utilisateur Linux d'exécuter une commande avec les droits d'un autre ?","sudo","chmod","ls","cat",
 "sudo applique une politique définie dans /etc/sudoers."),
(2,"Quel fichier définit la politique de sudo ?","/etc/sudoers","/etc/passwd","/etc/hosts","/etc/motd",
 "On l'édite avec visudo pour éviter les erreurs de syntaxe."),
(3,"Pourquoi une règle sudo « ALL=(ALL) ALL » pour un utilisateur est-elle risquée ?","Elle lui donne tous les droits sur le système","Elle interdit sudo","Elle chiffre les fichiers","Elle supprime son compte",
 "Elle équivaut à un accès administrateur complet."),
(2,"Quelle bonne pratique limite sudo ?","Autoriser des commandes précises et journaliser leur usage","Autoriser tout","Désactiver les journaux","Partager le mot de passe root",
 "On donne des droits ciblés et traçables."),
(2,"Pourquoi interdit-on la connexion SSH directe du compte root ?","Pour attribuer les actions à des personnes précises","Pour accélérer SSH","Pour supprimer les mots de passe","Pour éviter les journaux",
 "On se connecte avec un compte nominatif puis on élève les droits."),
(2,"Quel mécanisme d'authentification SSH est préféré aux mots de passe ?","Les clés publiques protégées par une phrase secrète","Le mot de passe court","Un compte partagé","L'accès anonyme",
 "Les clés réduisent le risque de force brute et facilitent la révocation."),
(2,"Comment révoque-t-on l'accès SSH d'un salarié par clé ?","En retirant sa clé publique des fichiers autorisés","En changeant le nom du serveur","En redémarrant","En changeant la couleur du terminal",
 "La clé publique est la preuve d'accès : on la retire (ou on la fait expirer)."),
(2,"Quelle option limite l'impact d'un service compromis sous Linux ?","Exécuter le service sous un compte dédié sans privilèges","L'exécuter en root","L'exécuter sans journal","L'exécuter sur tous les ports",
 "Un compte de service minimal réduit ce qu'un attaquant peut faire."),
(2,"Qu'est-ce qu'un compte de service ?","Un compte utilisé par une application et non par une personne","Un compte de maintenance du bâtiment","Un compte invité","Un compte de messagerie",
 "Leur mot de passe doit être long, géré et tournant ; leurs droits minimaux."),
(3,"Quel danger présente un compte de service avec mot de passe qui n'expire jamais et privilèges élevés ?","Une cible de choix pour un attaquant, rarement surveillée","Aucun danger","Un excès de journaux","Un ralentissement",
 "Les comptes de service sont souvent oubliés dans les revues."),
(2,"Quel mécanisme cloud définit ce qu'une identité peut faire ?","Une politique IAM attachée à un rôle ou utilisateur","Un fond d'écran","Un disque dur","Un navigateur",
 "Les fournisseurs cloud utilisent des politiques IAM en JSON ou équivalent."),
(2,"Quelle bonne pratique s'applique à une politique IAM cloud ?","Éviter les permissions « * » sur toutes les ressources","Donner tous les droits à tous","Désactiver les journaux","Utiliser un seul compte pour tous",
 "On cible les actions et les ressources nécessaires."),
(2,"Pourquoi privilégier des rôles temporaires pour les applications cloud ?","Les identifiants sont de courte durée et n'ont pas à être stockés","Ils sont plus lourds","Ils ne se révoquent pas","Ils sont anonymes",
 "Cela réduit le risque de fuite d'une clé d'accès statique."),
(2,"Quel risque courant dans le cloud concerne les stockages de fichiers ?","Un stockage laissé en accès public par erreur","Un stockage trop petit","Un stockage chiffré","Un stockage redondant",
 "Les fuites de données par mauvaise configuration sont fréquentes."),
(2,"Que fait la journalisation d'un système de contrôle d'accès ?","Enregistre les accès accordés, refusés et les changements de droits","Supprime les droits","Chiffre les sessions","Sauvegarde les fichiers",
 "Elle sert à détecter des abus et à enquêter."),
(2,"Quel événement doit absolument être journalisé ?","La modification des droits d'administration","Le changement de fond d'écran","L'ouverture d'un fichier personnel Public","La mise en veille",
 "Les changements de privilèges sont des événements sensibles."),
(2,"Pourquoi centralise-t-on les journaux sur un serveur distinct ?","Pour empêcher leur effacement par un attaquant qui a compromis la machine","Pour réduire l'espace","Pour supprimer les doublons","Pour accélérer le réseau",
 "Un journal local peut être modifié par celui qui prend le contrôle de la machine."),
(2,"Quel outil agrège et corrèle les journaux de sécurité ?","Un SIEM","Un tableur","Un navigateur","Un lecteur PDF",
 "Le SIEM détecte des séquences anormales sur plusieurs sources."),
(3,"Quel indicateur d'alerte est typique d'un abus de droits ?","Un accès massif à des fichiers hors du périmètre habituel","Une connexion unique le matin","Un changement de fond d'écran","Une mise à jour automatique",
 "L'analyse de comportement détecte les écarts."),
(2,"Quelle règle s'applique au stockage des mots de passe côté serveur ?","Les stocker sous forme de hash salé avec un algorithme adapté","Les stocker en clair","Les chiffrer avec une clé partagée","Les stocker dans un tableur",
 "Un hash lent et salé rend la récupération en masse beaucoup plus difficile."),
(2,"À quoi sert le « sel » ajouté à un mot de passe avant hachage ?","Empêcher que deux mots de passe identiques donnent le même hash et limiter les tables précalculées","Raccourcir le mot de passe","Chiffrer le mot de passe","Supprimer le mot de passe",
 "Un sel unique par utilisateur oblige l'attaquant à travailler compte par compte."),
(2,"Quel avantage a un gestionnaire de mots de passe pour une organisation ?","Il permet des mots de passe uniques et robustes sans les mémoriser","Il supprime le MFA","Il partage les mots de passe avec tous","Il remplace les rôles",
 "Il réduit la réutilisation de mots de passe d'un service à l'autre."),
]
